pub async fn submit_update(
    &mut operation: OperationWithClockTag,
    wait: WaitUntil,
    hw_measurement_acc: HwMeasurementAcc,
) -> CollectionResult<SubmitOutcome> {
    let (callback_sender, callback_receiver) = if wait.needs_callback() {
        let (tx, rx) = oneshot::channel();
        (Some(tx), Some(rx))
    } else {
        (None, None)                       // wait=false → NO callback channel ever created
    };
    ...
    let (operation_id, _wal_lock) = match self.wal.lock_and_write(&mut operation).await { ... };  // WAL write — only durability check
    ...
    channel_permit.send(UpdateSignal::Operation(OperationData {
        op_num: operation_id,
        operation: operation_in_ram,
        sender: callback_sender,          // None when wait=false
        wait_for_deferred: wait.wait_for_deferred(),
        hw_measurements: hw_measurement_acc,
    }));
    Ok(SubmitOutcome::Submitted { operation_id, receiver: callback_receiver, clock_tag })
}
