pub enum WaitUntil {
    /// Wait until the operation is written in WAL.
    ///
    /// Corresponds with wait=false, acknowledging immediately.
    Wal,
    ...
    pub fn needs_callback(&self) -> bool {
        match self { WaitUntil::Segment | WaitUntil::Visible => true, WaitUntil::Wal => false }
    }
impl From<bool> for WaitUntil { fn from(wait: bool) -> Self { if wait { WaitUntil::Visible } else { WaitUntil::Wal } } }
